function render(view){state.view=view;panel.removeAttribute('data-locale-safe');document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('selected',b.dataset.view===view));primary.style.display='';({dashboard,vendors:vendorsView,deals,placements,leads,seo,sitemap:sitemapView,settings:settingsView,ontology:ontologyView}[view]||dashboard)();if(view!=='sitemap')primary.onclick=()=>view==='vendors'||view==='dashboard'?openVendor():toast(`${primary.textContent.trim()}: demo action`);panel.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>b.dataset.action==='route-registry'?openRouteRegistry():toast(`${b.dataset.action}: demo control opened`));if(window.lucide)window.lucide.createIcons({attrs:{'stroke-width':1.75}});if(typeof adminLocale!=='undefined')applyAdminLocale()}
function openRouteRegistry(){const routes=window.MDP_PUBLIC_ROUTES||[];let modal=document.querySelector('.route-registry-modal');if(!modal){document.body.insertAdjacentHTML('beforeend',`<div class="admin-modal route-registry-modal"><section><div class="card-heading"><div><div class="eyebrow">/ BUILD OUTPUT</div><h2>Public route registry</h2></div><button class="table-action" data-registry-close aria-label="Close">×</button></div><p class="stat-foot registry-summary"></p><input class="registry-search" type="search" placeholder="Search routes…"><div class="registry-list"></div></section></div>`);modal=document.querySelector('.route-registry-modal');modal.onclick=e=>{if(e.target===modal||e.target.closest('[data-registry-close]'))modal.classList.remove('show')};modal.querySelector('.registry-search').oninput=()=>renderRouteRegistryRows(modal,routes)}modal.querySelector('.registry-summary').textContent=`${routes.length} public URLs · Admin routes are excluded`;modal.classList.add('show');renderRouteRegistryRows(modal,routes);if(typeof adminLocale!=='undefined')applyAdminLocale()}
function renderRouteRegistryRows(modal,routes){const query=modal.querySelector('.registry-search').value.trim().toLowerCase();const matches=routes.filter(route=>route.toLowerCase().includes(query));modal.querySelector('.registry-list').innerHTML=matches.map(route=>`<a href="${route}"><code>${route||'/'}</code><span>↗</span></a>`).join('')||`<div class="empty-state">No routes match this search.</div>`}
function openVendor(name=''){
  let modal=document.querySelector('.vendor-editor')?.closest('.admin-modal');
  const existing=vendors.find(v=>v[0]===name),detail=existing?.[4]||{};
  const categories=(window.MDP_CATEGORY_LIST||['Marketing Analytics, Tracking & Attribution','Cloud/Data Integration Platform','Data Visualization Technology','Conversion Rate Optimization / Personalization','Advertising Technology','Visitor Identification Software','Affiliate Marketing or Performance-Based Advertising','Content Marketing Technology','Search Marketing Technology','AIEO / GEO Tools','Social Media Technology','Social Listening','Conversation Marketing Technology','LINE OA / LINE CRM','CRM & Marketing Automation','Consent Management','Customer Data Platform (CDP)','Commerce']);
  if(!modal){document.body.insertAdjacentHTML('beforeend',`<div class="admin-modal"><section class="vendor-editor"><div class="eyebrow">/ VENDOR PROFILE</div><h2></h2><div class="vendor-editor-grid"><label>Company / product name<input name="name" required></label><label>Primary category<select name="category">${categories.map(c=>`<option>${c}</option>`).join('')}</select></label><label>Website<input name="website" placeholder="https://"></label><label>Pricing model<input name="pricingModel" placeholder="Subscription, usage-based…"></label><label>Supported languages<input name="supportedLanguages" placeholder="Thai, English"></label><label>Company name review<select name="companyNameReview"><option>Pending</option><option>Confirmed</option><option>Correction needed</option></select></label><label>Logo verification<select name="logoReview"><option>Pending</option><option>Official asset · pending verification</option><option>Mock logo · replace or approve</option><option>Mock logo · retained as mock</option><option>Approved</option><option>Correction needed</option></select></label><label>Logo source asset filename<input name="logoSource" placeholder="Blank means MOCK initials"><small>Choose a .webp filename from assets/vendor-logos/. The extracted mark is not confirmed as official until the team approves it.</small></label><label>Target market<input name="market" placeholder="Thailand, Southeast Asia"></label><label>Integrations<textarea name="integrations" rows="2" placeholder="LINE OA, Salesforce…"></textarea></label><label>PDPA readiness<input name="pdpa" placeholder="Not yet verified"></label><label>English summary<textarea name="descriptionEn" rows="3"></textarea></label><label>Thai summary<textarea name="descriptionTh" rows="3"></textarea></label><label>Profile status<select name="status"><option>Draft</option><option>Needs review</option><option>Published</option></select></label></div><p class="settings-note">Vendor edits save to Cloudflare D1. Published profiles update on the public page; logo and company name remain marked for team verification until confirmed.</p><div class="modal-actions"><button class="table-action" data-modal-close>Cancel</button><button class="button" data-modal-save>Save vendor details</button></div></section></div>`);modal=document.querySelector('.admin-modal');modal.onclick=e=>{if(e.target===modal||e.target.closest('[data-modal-close]'))modal.classList.remove('show');if(e.target.closest('[data-modal-save]'))saveVendorFromModal(modal)};}
  modal.querySelector('h2').textContent=name?'Review vendor':'Add vendor';const data=existing||[name,'Marketing Analytics, Tracking & Attribution','Provided company list','Draft',{},''];const source=window.MDP_VENDORS?.find(v=>v.slug===data[5]||v.name===name),logoAsset=detail.logoAsset||source?.logoAsset||window.MDP_VENDOR_LOGO_ASSETS?.[source?.name||name]||'',logoType=detail.logoType||(logoAsset?'source-asset':'mock');modal.dataset.vendorSlug=data[5]||source?.slug||'';
  const set=(key,value)=>{const el=modal.querySelector(`[name="${key}"]`);if(el)el.value=value??''};set('name',name);set('category',data[1]);set('website',detail.website);set('pricingModel',detail.pricingModel);set('supportedLanguages',detail.supportedLanguages);set('market',detail.market);set('integrations',detail.integrations);set('pdpa',detail.pdpa);set('descriptionEn',detail.descriptionEn);set('descriptionTh',detail.descriptionTh);set('status',data[3]);set('companyNameReview',detail.companyNameReview||'Pending');set('logoReview',detail.logoReview||(logoAsset?'Official asset · pending verification':'Mock logo · replace or approve'));set('logoSource',logoAsset);modal.classList.add('show');if(typeof adminLocale!=='undefined')applyAdminLocale();
}
async function saveVendorFromModal(modal){const get=name=>modal.querySelector(`[name="${name}"]`).value.trim(),name=get('name');if(!name){modal.querySelector('[name="name"]').focus();return}const record={category:get('category'),website:get('website'),pricingModel:get('pricingModel'),supportedLanguages:get('supportedLanguages'),market:get('market'),integrations:get('integrations'),pdpa:get('pdpa'),descriptionEn:get('descriptionEn'),descriptionTh:get('descriptionTh'),status:get('status'),companyNameReview:get('companyNameReview'),logoReview:get('logoReview'),logoType:/^[a-z0-9._-]+\.webp$/i.test(get('logoSource'))?'source-asset':'mock',logoAsset:/^[a-z0-9._-]+\.webp$/i.test(get('logoSource'))?get('logoSource'):''};const row=vendors.find(v=>v[5]===modal.dataset.vendorSlug||v[0]===name),source=window.MDP_VENDORS?.find(v=>v.slug===modal.dataset.vendorSlug||v.name===name);let slug=modal.dataset.vendorSlug||row?.[5]||source?.slug||String(name).normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');if(!slug)slug=`vendor-${crypto.randomUUID().slice(0,8)}`;modal.dataset.vendorSlug=slug;const button=modal.querySelector('[data-modal-save]');button.disabled=true;try{const response=await fetch('/api/admin/vendors',{method:'PUT',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify({slug,name,data:record})}),out=await response.json();if(!response.ok)throw new Error(out.error||'Could not save vendor details');if(row){row[0]=name;row[1]=record.category;row[3]=record.status;row[4]={...row[4],name,...record};row[5]=slug}else vendors.unshift([name,record.category,'Admin-created record · D1',record.status,{name,...record},slug]);if(vendorCountNode)vendorCountNode.textContent=vendors.length;modal.classList.remove('show');if(state.view==='vendors')vendorsView();toast(record.status==='Published'?'Vendor saved to D1 and public profile is now published.':'Vendor saved to Cloudflare D1.');if(typeof adminLocale!=='undefined')applyAdminLocale()}catch(error){toast(error.message)}finally{button.disabled=false}}
async function loadVendorOverrides(){try{const response=await fetch('/api/admin/vendors',{credentials:'same-origin'});if(!response.ok)return;const result=await response.json();for(const item of result.vendors||[]){let row=vendors.find(v=>v[5]===item.slug);const data={...(item.data||{}),name:item.name};if(row){row[0]=item.name;row[1]=data.category||row[1];row[3]=data.status||row[3];row[4]={...row[4],...data};row[5]=item.slug;row[2]=String(item.updatedBy||'').startsWith('seed:')?'Imported from sponsor list · review pending':'Cloudflare D1 · edited by '+item.updatedBy}else vendors.unshift([item.name,data.category||'Needs verification',(String(item.updatedBy||'').startsWith('seed:')?'Imported from sponsor list · review pending':'Cloudflare D1 · edited by '+item.updatedBy),data.status||'Draft',data,item.slug]);}if(vendorCountNode)vendorCountNode.textContent=vendors.length;if(state.view==='vendors')vendorsView()}catch{}}
function exportVendorLogoReview(){const quote=value=>'"'+String(value??'').replace(/"/g,'""')+'"',rows=[['vendor_name','slug','logo_type','logo_asset','company_name_review','logo_review','team_decision'],...vendors.map(v=>{const asset=v[4]?.logoAsset||window.MDP_VENDOR_LOGO_ASSETS?.[v[0]]||'';return [v[0],v[5]||'',asset?'SOURCE IMAGE ASSET':'MOCK INITIALS',asset||'',v[4]?.companyNameReview||'Pending',v[4]?.logoReview||(asset?'Official asset · pending verification':'Mock logo · replace or approve'),(v[4]?.companyNameReview==='Correction needed'||v[4]?.logoReview==='Correction needed'?'Correction needed':v[4]?.companyNameReview==='Confirmed'&&['Approved','Mock logo · retained as mock'].includes(v[4]?.logoReview)?'Confirmed':'Pending team confirmation')]})];const a=document.createElement('a'),url=URL.createObjectURL(new Blob([rows.map(row=>row.map(quote).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));a.href=url;a.download='vendor-name-logo-review.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}

