function applyAdminLocale(){document.documentElement.lang=adminLocale;adminLocaleButton.textContent=adminLocale==='en'?'ไทย':'EN';const translationPairs=Object.entries(adminTranslations).sort((a,b)=>adminLocale==='th'?b[0].length-a[0].length:b[1].length-a[1].length);if(adminThemeButton){const themeLabel=adminLocale==='th'?(adminTheme==='dark'?'สว่าง':'มืด'):(adminTheme==='dark'?'Light':'Dark');if(adminThemeButton.textContent.trim()!==themeLabel){adminThemeButton.innerHTML=`<i data-lucide="${adminTheme==='dark'?'sun':'moon'}"></i> ${themeLabel}`;if(window.lucide)window.lucide.createIcons({attrs:{'stroke-width':1.75}})}};const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(node.parentElement?.closest('[data-locale-safe]'))continue;let text=node.nodeValue;for(const [en,th] of translationPairs)if(adminLocale==='th')text=text.replaceAll(en,th);else text=text.replaceAll(th,en);if(node.nodeValue!==text)node.nodeValue=text}document.querySelectorAll('[placeholder]').forEach(el=>{if(adminLocale==='th'&&el.placeholder==='Vendor name')el.placeholder='ชื่อผู้ให้บริการ';if(adminLocale==='en'&&el.placeholder==='ชื่อผู้ให้บริการ')el.placeholder='Vendor name';if(adminLocale==='th'&&el.placeholder==='Search routes…')el.placeholder='ค้นหา URL…';if(adminLocale==='th'&&el.placeholder==='Search vendors…')el.placeholder='ค้นหาผู้ให้บริการ…';if(adminLocale==='en'&&el.placeholder==='ค้นหา URL…')el.placeholder='Search routes…'});}
window.getAdminLocale=()=>adminLocale;window.initAdminConfig?.();
adminLocaleButton.onclick=()=>{adminLocale=adminLocale==='en'?'th':'en';localStorage.setItem('mdp-admin-locale',adminLocale);applyAdminLocale();window.dispatchEvent(new Event('mdp-admin-locale-change'));if(state.view==='settings'||state.view==='ontology')render(state.view)};
applyAdminLocale();
function setAdminTheme(theme){adminTheme=theme;document.documentElement.dataset.theme=theme;window.applyAdminAppearance?.();localStorage.setItem('mdp-admin-theme',theme);adminThemeButton.innerHTML=`<i data-lucide="${theme==='dark'?'sun':'moon'}"></i> ${adminLocale==='th'?(theme==='dark'?'สว่าง':'มืด'):(theme==='dark'?'Light':'Dark')}`;if(window.lucide)window.lucide.createIcons({attrs:{'stroke-width':1.75}})}setAdminTheme(adminTheme);adminThemeButton.onclick=()=>setAdminTheme(adminTheme==='dark'?'light':'dark');
document.querySelectorAll('[data-view]').forEach(button=>{if(['placements','leads','users'].includes(button.dataset.view))return;button.addEventListener('click',()=>render(button.dataset.view))});
